class Stack<T> {
  private readonly datos: T[] = [];

  push(item: T): void {
    this.datos.push(item);
  }

  pop(): T | undefined {
    return this.datos.pop();
  }

  peek(): T | undefined {
    return this.datos.at(-1);
  }
}

